using FitHub.Application.Analytics;using FitHub.Application.Notifications;using FitHub.Domain.Bookings;using FitHub.Domain.Communications;using FitHub.Domain.Memberships;using FitHub.Domain.Workouts;using FitHub.Infrastructure.Persistence;using Microsoft.EntityFrameworkCore;
namespace FitHub.Infrastructure.Notifications;
public sealed class NotificationService(FitHubDbContext db,TimeProvider timeProvider):INotificationService
{
    public async Task<IReadOnlyCollection<NotificationDto>> GetAsync(Guid userId,bool generateMemberNotifications=true,CancellationToken ct=default){if(generateMemberNotifications)await GenerateAsync(userId,ct);return await db.Notifications.AsNoTracking().Where(x=>x.UserId==userId).OrderByDescending(x=>x.CreatedAt).Take(100).Select(x=>new NotificationDto(x.Id,x.Type.ToString(),x.Title,x.Message,x.IsRead,x.CreatedAt,x.ReadAt)).ToListAsync(ct);}
    public async Task<bool> MarkReadAsync(Guid userId,Guid id,CancellationToken ct=default){var item=await db.Notifications.SingleOrDefaultAsync(x=>x.Id==id&&x.UserId==userId,ct);if(item is null)return false;item.MarkRead(timeProvider.GetUtcNow());await db.SaveChangesAsync(ct);return true;}
    public async Task CreateFaultStatusAsync(Guid userId,Guid reportId,string equipmentName,string status,CancellationToken ct=default){var key=$"fault:{reportId}:{status}";if(await db.Notifications.AnyAsync(x=>x.UserId==userId&&x.DeduplicationKey==key,ct))return;db.Notifications.Add(new Notification(userId,NotificationType.FaultReportStatusUpdate,"Fault report updated",$"Your report for {equipmentName} is now {status}.",key));await db.SaveChangesAsync(ct);}
    private async Task GenerateAsync(Guid userId,CancellationToken ct)
    {
        var now=timeProvider.GetUtcNow();var existing=(await db.Notifications.AsNoTracking().Where(x=>x.UserId==userId).Select(x=>x.DeduplicationKey).ToListAsync(ct)).ToHashSet(StringComparer.Ordinal);var pending=new List<Notification>();
        var membership=await db.Memberships.AsNoTracking().Where(x=>x.UserId==userId&&x.Status==MembershipStatus.Active&&x.EndsAt>now&&x.EndsAt<=now.AddDays(7)).OrderBy(x=>x.EndsAt).FirstOrDefaultAsync(ct);if(membership is not null)Add(NotificationType.MembershipExpiry,"Membership expiring",$"Your membership expires on {membership.EndsAt:yyyy-MM-dd}.",$"membership-expiry:{membership.Id}");
        var classes=await db.ClassBookings.AsNoTracking().Include(x=>x.ClassSchedule).Where(x=>x.UserId==userId&&x.Status==BookingStatus.Confirmed&&x.ClassSchedule.Status==ClassScheduleStatus.Approved&&x.ClassSchedule.StartsAt>now&&x.ClassSchedule.StartsAt<=now.AddHours(24)).ToListAsync(ct);foreach(var booking in classes)Add(NotificationType.ClassReminder,"Class reminder",$"{booking.ClassSchedule.Name} starts at {booking.ClassSchedule.StartsAt:g}.",$"class-reminder:{booking.Id}");
        var sessions=await db.WorkoutSessions.AsNoTracking().Include(x=>x.ExerciseLogs).ThenInclude(x=>x.Exercise).Include(x=>x.ExerciseLogs).ThenInclude(x=>x.Sets).Where(x=>x.UserId==userId&&x.Status==WorkoutSessionStatus.Completed).OrderByDescending(x=>x.EndedAt).ToListAsync(ct);var last=sessions.FirstOrDefault()?.EndedAt;if(last is null||now-last.Value>=TimeSpan.FromDays(7))Add(NotificationType.WorkoutConsistency,"Workout consistency", "No completed workout has been recorded in the last 7 days. Plan a manageable session when recovered.",$"workout-consistency:{now:yyyy-MM-dd}");
        var attendance=await db.Attendances.AsNoTracking().Where(x=>x.UserId==userId&&x.CheckedInAt>=now.AddDays(-90)).Select(x=>x.CheckedInAt).ToListAsync(ct);var week=AnalyticsRules.StartOfUtcWeek(now);var previousStreak=AnalyticsRules.CurrentWeeklyStreak(attendance,now.AddDays(-7));if(previousStreak>=2&&!attendance.Any(x=>x>=week))Add(NotificationType.StreakWarning,"Attendance streak warning",$"Your previous attendance streak was {previousStreak} weeks and no visit is recorded this week.",$"streak-warning:{week:yyyy-MM-dd}");
        var sets=sessions.SelectMany(s=>s.ExerciseLogs.SelectMany(log=>log.Sets.Where(set=>set.WeightKg>0).Select(set=>new{Set=set,log.Exercise.Name,log.ExerciseId,At=s.EndedAt??s.StartedAt}))).ToList();foreach(var group in sets.GroupBy(x=>new{x.ExerciseId,x.Name})){var max=group.Max(x=>x.Set.WeightKg!.Value);var record=group.Where(x=>x.Set.WeightKg==max).OrderBy(x=>x.At).ThenBy(x=>x.Set.SetNumber).First();if(record.At>=now.AddDays(-7))Add(NotificationType.PersonalRecord,"Personal record",$"New recorded best for {record.Name}: {max:0.#} kg.",$"personal-record:{record.Set.Id}");}
        if(pending.Count>0){db.Notifications.AddRange(pending);await db.SaveChangesAsync(ct);}
        void Add(NotificationType type,string title,string message,string key){if(existing.Add(key))pending.Add(new Notification(userId,type,title,message,key));}
    }
}
